(function(root){
  'use strict';
  const DETAILS={"D1":{"reason":"Bei einem glatten, empfindlichen Werkstück reicht die Bezeichnung „Parallelgreifer“ noch nicht als Auswahl. Zuerst klärst du Material, Masse, Schwerpunkt und Oberfläche. Dann überlegst du, ob die Finger durch Reibung halten oder das Teil formschlüssig umgreifen. Erst danach prüfst du den nötigen Hub und die Kräfte aus Bewegung und Gewicht.","example":"Ein Vakuumsauger kann bei einer glatten Platte sinnvoll sein, bei einem porösen Werkstück aber viel Leckluft benötigen. Ein Magnetgreifer eignet sich nur für passende magnetisierbare Werkstoffe. Die Form der Backen beschreibt die Bewegung; pneumatisch oder elektrisch beschreibt den Antrieb. Das sind zwei verschiedene Einteilungen."},"D2":{"reason":"Eine abgeschaltete Versorgung bedeutet nicht automatisch eine drucklose Anlage: Ein Rückschlagventil kann Druck einschließen, ein Speicher Energie halten und eine angehobene Last weiter fallen. Deshalb gehört zur Erklärung immer die Verbindung von Gefährdung, Energiequelle und wirksamer Schutzmaßnahme.","example":"Beispiel: Beim Lösen eines Schlauchs kann gespeicherte Druckluft einen Peitscheneffekt auslösen. Das Schutzkonzept muss gespeicherte Energie beherrschen und unerwartete Bewegung verhindern. Die fünf Regeln im Fachpunkt sind als zusammenhängende Freigabekette zu verstehen; ein einzelner Schritt ersetzt die anderen nicht. Maßgeblich bleibt die konkrete betriebliche Freigabe."},"D3":{"reason":"Die Kolbenstange überträgt vor allem die vorgesehene axiale Kraft. Eine zusätzliche Führung nimmt seitliche Kräfte und Momente auf, damit diese nicht unzulässig auf Kolbenstange und Dichtung wirken. Besonders bei einem seitlich auskragenden Greifer entsteht neben einer Kraft auch ein Biegemoment.","example":"Bei der mechanischen Kopplung eines kolbenstangenlosen Antriebs ist der äußere Schlitten durch eine konstruktive Verbindung mit dem Kolben gekoppelt. Bei magnetischer Kopplung wirkt die Kraft durch die geschlossene Zylinderwand. Eine Überlast kann die magnetische Kopplung lösen; welche Lasten zulässig sind, ergibt sich aus den Herstellerdaten."},"D4":{"reason":"Denke beim Legieren an den Unterschied zwischen Zusammensetzung und Gefüge. Eine andere Zusammensetzung verändert, welche Atome und Phasen nach dem Erstarren vorliegen. Daraus können andere Festigkeit, Bearbeitbarkeit und Korrosionseigenschaften entstehen. Nicht jede Eigenschaft wird gleichzeitig besser.","example":"Bei einer Armatur genügt daher „Messing ist gelb und rostet nicht“ nicht. Du begründest, warum eine passende Kupfer-Zink-Sorte gut herstellbar ist und zum Medium passen muss. Kupfer mit Zinn ist dagegen Zinnbronze. „Bronze“ und „Messing“ sind keine austauschbaren Namen für alle gelblichen Kupferlegierungen."},"D5":{"reason":"Korrosion ist eine Reaktion des Werkstoffs mit seiner Umgebung, die eine nachteilige Veränderung bewirken kann. Entscheidend ist die Kombination: Derselbe Werkstoff kann in trockener Luft ausreichend beständig und in einem anderen Medium ungeeignet sein.","example":"Beispiel: Zwei unterschiedliche Metalle berühren sich und sind durch einen leitfähigen Feuchtigkeitsfilm verbunden. Dann kann Kontaktkorrosion entstehen. Zur Auswahl gehören deshalb nicht nur ein beständiger Werkstoff, sondern auch die Paarung, konstruktive Entwässerung, Beschichtungen und die Betriebsbedingungen. „Edelstahl“ allein beschreibt noch keine universelle Beständigkeit."},"D6":{"reason":"Der Molekülaufbau erklärt das Wärmeverhalten: Thermoplaste besitzen unvernetzte beziehungsweise nicht dauerhaft chemisch vernetzte Ketten und können innerhalb ihres Verarbeitungsbereichs erweichen. Bei Duroplasten verhindert eine enge Vernetzung erneutes Aufschmelzen; bei Elastomeren ermöglicht eine weitmaschige Vernetzung große rückstellbare Verformung.","example":"Vergleiche einen umformbaren thermoplastischen Schutzdeckel, ein duroplastisches Bauteil mit hoher Formstabilität und eine elastomere Dichtung. Erwärmen macht aus einem Duroplast keinen wiederverarbeitbaren Thermoplast. Auch ein Elastomer ist kein beliebig schmelzbarer Gummi: Zu hohe Temperatur kann es dauerhaft schädigen."},"D7":{"reason":"Pneumatik eignet sich häufig für schnelle, einfache Bewegungen. Die kompressible Luft speichert jedoch Energie und verändert unter Last ihr Volumen. Das hilft beim Verständnis von Nachgiebigkeit, Grenzen der Positioniergenauigkeit und dem Verhalten bei Druckänderungen.","example":"Abluftgeräusch entsteht beim Ausströmen und Entspannen der Luft. Ein Schalldämpfer beeinflusst diesen Vorgang, muss aber zum Volumenstrom passen. Ein zugesetzter Dämpfer kann Gegendruck verursachen und die Bewegung verändern. Geräuschminderung und störungsfreie Funktion müssen zusammen betrachtet werden."},"D8":{"reason":"Im Ejektor wird Druckenergie in hohe Strömungsgeschwindigkeit umgewandelt. Im vorgesehenen Ansaugbereich entsteht ein niedrigerer statischer Druck, sodass Umgebungsluft angesaugt wird. Diese Erklärung verbindet die drei Wege: Versorgungsluft hinein, angesaugte Luft hinzu, gemeinsame Abluft hinaus.","example":"Der Sauger „zieht“ das Werkstück nicht durch eine eigene Zugkraft aus dem Nichts. Die Druckdifferenz zwischen Umgebung und Sauger wirkt auf die wirksame Fläche. F = Δp · A beschreibt die ideale Haltekraft. Leckage, Oberfläche, Lage und Dynamik begrenzen die nutzbare Kraft; die Formel ist noch keine vollständige Auslegung."},"D9":{"reason":"Unterscheide zuerst eine ruhende Dichtstelle, etwa zwischen Gehäusehälften, von einer bewegten Dichtstelle an einer Kolbenstange oder Welle. Bei Bewegung beeinflussen Reibung, Verschleiß und Schmierung die Wahl zusätzlich zur Dichtwirkung.","example":"Ein Werkstoff ist nur geeignet, wenn Medium, Temperatur und mechanische Beanspruchung passen. Eine gegen ein bestimmtes Öl beständige Dichtung kann gegenüber einem anderen Medium ungeeignet sein. Die Bezeichnung eines Elastomers ist deshalb ein Auswahlhinweis; die konkrete Freigabe ergibt sich aus Werkstoff- und Herstellerdaten."},"D10":{"reason":"Bei der Festigkeitsklasse 8.8 ergibt die erste Zahl mal 100 die nominelle Zugfestigkeit: 8 × 100 = 800 N/mm². Die zweite Zahl durch zehn ergibt das nominelle Verhältnis der Streckgrenze zur Zugfestigkeit: 0,8. Daraus folgt 800 × 0,8 = 640 N/mm².","example":"Die Werte beschreiben den Schraubenwerkstoff innerhalb der zugehörigen Regeln, nicht automatisch die zulässige Belastung der ganzen Verbindung. Vorspannung, Gewinde, Länge, Reibung, Fügeteile und Lastart bleiben wichtig. Bei einer Durchsteckschraube erfolgt die Verschraubung typischerweise mit einer Mutter; eine Stiftschraube hat eine andere Befestigungsanordnung."},"D11":{"reason":"Beim Formschluss verhindern ineinandergreifende Formen die Relativdrehung. Beim Kraftschluss entsteht die Übertragung durch Reibung aus einer Anpresskraft. Beim Stoffschluss hält eine stoffliche Verbindung. Diese Wirkprinzipien sagen mehr über die Funktion aus als der bloße Name eines Verbindungselements.","example":"Eine Passfeder kann Drehmoment über die Flanken übertragen. Ob die Nabe axial verschiebbar sein soll, hängt von der Ausführung und der Sicherung ab. Bei einer Keilwelle greifen mehrere über den Umfang verteilte Profile ineinander. Drehmomentübertragung und axiale Festlegung sind zwei getrennt zu erklärende Aufgaben."},"D12":{"reason":"Ein Schwenkspanner soll normalerweise erst in die vorgesehene Lage schwenken und danach spannen. Wird die Bewegung blockiert, kann eine Druckmeldung trotzdem entstehen. Druck allein beweist deshalb nicht, dass das Werkstück richtig und sicher gespannt ist.","example":"Vergleiche die Aussage der Signale: Ein Endlagensensor meldet eine Position, ein Drucksensor einen Druck und ein werkstückbezogener Sensor die Anwesenheit beziehungsweise Lage. Eine sichere Überwachung braucht die für die Gefährdung passende Aussage. Ein beliebiger Sensor wird nicht allein durch seinen Einbau zur Sicherheitsfunktion."},"D13":{"reason":"Der elektrische Sollwert wirkt über den Proportionalmagneten auf das Ventil. Die geänderte Öffnung beeinflusst je nach Ventil den Volumenstrom oder den Druck. Damit wird aus einem reinen Ein/Aus-Befehl eine veränderliche Stellgröße.","example":"„Proportional“ bedeutet nicht, dass jede reale Anlage unter allen Bedingungen exakt linear arbeitet. Totbereich, Hysterese, Reibung, Druckdifferenz und Last können das Verhalten beeinflussen. Eine Regelung benötigt zusätzlich einen Istwert und einen Soll-Ist-Vergleich; ein Proportionalventil allein ist noch kein geschlossener Regelkreis."},"D14":{"reason":"Unlösbar bedeutet, dass eine Trennung typischerweise einen zerstörenden Eingriff an der Verbindung erfordert. Das kann beim Nieten das Entfernen des Niets oder beim Schweißen das Trennen der Naht sein. Eine spätere Zerlegung ist nicht gleichbedeutend mit zerstörungsfreier Lösbarkeit.","example":"Beim Niet müssen Fügeteil und Niet nicht zwingend aus exakt demselben Werkstoff bestehen. Entscheidend ist ihre Eignung als Paarung: Korrosionsverhalten, Umformbarkeit, Festigkeit und Umgebung. Ein ungünstiges Metallpaar in feuchter Umgebung kann Kontaktkorrosion begünstigen."},"D15":{"reason":"Eine Feder verbindet Kraft, Verformung und gespeicherte Energie. Für eine ideale lineare Feder gilt F = c · s. Bei c = 10 N/mm und s = 5 mm ergibt sich F = 50 N. Die gespeicherte Energie ist bei dieser idealen Kennlinie W = ½ · F · s = 0,125 J.","example":"Die lineare Formel gilt nicht für jede Feder über ihren gesamten Weg. Vorspannung, progressive Kennlinie, zulässige Spannungen und Ermüdung können wichtig sein. Eine Feder kann Kräfte aufbringen, Stöße aufnehmen oder eine Rückstellung bewirken. Ihre Bauform muss zur Belastungsrichtung und zum verfügbaren Raum passen."},"D16":{"reason":"Ein Zahnradpaar koppelt Drehzahlen und Drehmomente. Bei idealer verlustfreier Übertragung bleibt die Leistung näherungsweise gleich: Eine kleinere Abtriebsdrehzahl geht mit einem größeren Abtriebsdrehmoment einher. Reale Wirkungsgrade vermindern die nutzbare Leistung.","example":"Beispiel: Ein Rad mit 20 Zähnen treibt eines mit 40 Zähnen. Der Abtrieb läuft halb so schnell; das ideale Drehmoment verdoppelt sich. Außenverzahnte Räder drehen dabei gegensinnig. Ob die Achsen parallel, sich schneidend oder windschief sind, führt zu unterschiedlichen geeigneten Zahnradbauarten."},"D17":{"reason":"Ordne jedem Trieb zuerst sein Wirkprinzip zu. Ein üblicher Keilriemen überträgt durch Reibung, eine Kette und ein Zahnriemen durch Formschluss. Zahnräder stehen unmittelbar im Eingriff. Daraus folgen Unterschiede bei Schlupf, Genauigkeit und konstruktiv möglichem Abstand.","example":"Ein räumlich weiter entfernter Lüfterantrieb kann mit Riemen zweckmäßig sein, ein kompakter genauer Antrieb mit Zahnrädern. Eine Kette kann größere Kräfte bei passenden Abständen übertragen, braucht aber eine geeignete Schmierung und Spannung. Die konkrete Wahl ist immer eine begründete Abwägung."},"D18":{"reason":"Beim Gleitlager gleiten die Flächen aufeinander beziehungsweise über einen Schmierfilm. Beim Wälzlager rollen Wälzkörper zwischen den Laufbahnen. Die Bauform bestimmt, welche radialen und axialen Kräfte aufgenommen werden und wie gut eine Winkelfehlstellung vertragen wird.","example":"Fett haftet gut und kann eine einfache Schmierlösung ermöglichen. Umlaufendes Öl kann zusätzlich Wärme und Verunreinigungen abführen, benötigt aber ein passendes Versorgungskonzept. „Öl ist immer besser“ ist daher keine Begründung. Last, Drehzahl, Temperatur, Umgebung und Wartung entscheiden gemeinsam."},"D19":{"reason":"Induktive Einkopplung entsteht durch ein veränderliches Magnetfeld und hängt unter anderem von der wirksamen Schleifenfläche ab. Kapazitive Einkopplung hängt mit elektrischen Feldern und Kapazitäten zusammen. Galvanische Kopplung nutzt einen gemeinsamen leitfähigen Pfad beziehungsweise gemeinsame Impedanzen.","example":"Werden Hin- und Rückleiter gemeinsam und verdrillt geführt, wird die Schleifenfläche kleiner. Abstand zu störenden Leistungskabeln kann ebenfalls helfen. Schirmung, Potentialausgleich und Leitungsführung sind nach dem Gesamtkonzept auszuführen; ein nur irgendwie angeschlossener Schirm löst nicht jedes EMV-Problem."},"D20":{"reason":"Visualisierung übersetzt Prozessdaten in eine verständliche Darstellung. Eine Temperaturkurve zeigt beispielsweise einen Verlauf, eine Grenzwertmeldung macht einen kritischen Zustand sichtbar. Der Nutzen entsteht erst, wenn die Anzeige die richtige Information zum richtigen Zeitpunkt liefert.","example":"Ein HMI ist die Bedien- und Anzeigeoberfläche, nicht automatisch die ausführende Steuerung. Ein angezeigter Zustand kann durch Kommunikationsfehler oder falsche Zuordnung vom echten Zustand abweichen. Für die Erklärung trennst du daher Messwerterfassung, Datenübertragung, Verarbeitung und Darstellung."},"D21":{"reason":"Eine Kupplung verbindet Wellen zur Übertragung von Drehmoment und kann je nach Bauart zusätzliche Aufgaben erfüllen: Versatz ausgleichen, Schwingungen dämpfen, schalten oder bei Überlast begrenzen. Nicht jede Kupplung erfüllt alle diese Aufgaben.","example":"Eine elastische Kupplung kann begrenzten Versatz und Stöße aufnehmen; eine starre Kupplung verlangt eine entsprechend genaue Ausrichtung. Eine Rutschkupplung begrenzt dagegen übertragbares Drehmoment. Beim Erkennen einer Abbildung begründest du die Zuordnung an ihren Bauteilen und der Bewegung, nicht nur am äußeren Umriss."},"D22":{"reason":"Beim Keilriemen vergrößert die Keilwirkung die wirksame Anpressung an den Flanken. Die Übertragung bleibt kraftschlüssig und kann Schlupf zeigen. Beim Zahnriemen greifen Zähne in passende Lücken; die Bewegung wird formschlüssig übertragen.","example":"Für eine zeitlich abgestimmte Bewegung ist der Zahnriemen oft günstiger als ein schlupfender Riemen. Trotzdem bleiben Dehnung, Spannung, Verschleiß und zulässige Kräfte relevant. Ein Zahnriemen ist kein wartungs- oder verschleißfreies Bauteil, nur weil er formschlüssig arbeitet."},"D23":{"reason":"Bei CEE erfüllen Farbe, geometrische Codierung und Kontaktanordnung unterschiedliche Funktionen. Die Farbe erleichtert die Zuordnung eines Spannungsbereichs; mechanische Merkmale erschweren das falsche Zusammenstecken. Eine Farbe allein ist keine ausreichende Identifikation für eine sichere Anwendung.","example":"Der Schutzkontakt soll beim Stecken vor den aktiven Kontakten verbinden und beim Ziehen später trennen. Ein Pilotkontakt kann eine Schaltfunktion so steuern, dass die Hauptkontakte beim geeigneten Konzept lastfrei getrennt werden. Schutzkontakt und Pilotkontakt haben unterschiedliche Aufgaben und dürfen nicht gleichgesetzt werden."},"D24":{"reason":"Vergleiche einen Trieb immer mit derselben Kriterienliste: Kraft und Drehmoment, Achsabstand, Genauigkeit, Geräusch, Umgebung, Schmierung und Wartung. Nur so wird aus einer Aufzählung eine nachvollziehbare Auswahlentscheidung.","example":"Eine Kette kann im Vergleich zum Riemen eine formschlüssige Übertragung bieten, verursacht aber andere Geräusch- und Wartungsanforderungen. Ein Zahnradgetriebe kann kompakt und genau sein, braucht jedoch eine passende Lagerung und Schmierung. Ein Riemen kann dämpfend wirken und größere Abstände überbrücken."},"D25":{"reason":"Verfolge in der Originalzeichnung den Signalweg in zwei getrennten Ebenen: vom Taster über das Relais zur Ventilspule und anschließend vom Ventil zum Zylinder. Notiere für jeden Taster, welches elektrische Signal und welcher Luftweg entstehen.","example":"Für das Verhalten nach dem Loslassen ist entscheidend, ob das Ventil eine Federrückstellung oder eine speichernde beziehungsweise bistabile Funktion besitzt. Übertrage diese Eigenschaft erst nach dem Lesen des konkreten Symbols auf die Bewegung. Die Originalabbildung bleibt maßgeblich; ein anderes Ventil kann beim gleichen Tasterprinzip anders reagieren."},"D26":{"reason":"Ein typisches pneumatisches Einschaltzeitglied füllt über eine Drossel ein Volumen. Der Druck steigt verzögert, bis das zugeordnete Schaltelement umschaltet. Die Verzögerung entsteht also durch einen zeitlichen Druckaufbau, nicht durch ein elektrisches Uhrwerk.","example":"Beim Rücksetzen ermöglicht ein passend angeordnetes Rückschlagventil häufig ein rascheres Entlüften. Versorgungsschwankungen, Drosselstellung und Volumen beeinflussen die Zeit. Deshalb ist ein pneumatisches Zeitglied nicht automatisch so genau oder lastunabhängig wie eine geeignete elektronische Zeitfunktion."},"D27":{"reason":"Zerlege eine Leitungsbezeichnung von links nach rechts. A kennzeichnet hier eine nationale Ausführung; 05 steht für die Spannungsklasse 300/500 V, VV für die bezeichneten PVC-Isolations- und Mantelwerkstoffe. U beschreibt einen eindrähtigen Leiter. 3G1,5 bedeutet drei Adern einschließlich grün-gelbem Schutzleiter mit je 1,5 mm².","example":"Die Bezeichnung allein beantwortet noch nicht jede Verlegefrage. Temperatur, Feuchte, mechanische Beanspruchung, Befestigung und Herstellerfreigabe entscheiden mit. 3G und 3X sind nicht gleich: G weist auf eine enthaltene grün-gelbe Ader hin; X auf eine Ausführung ohne diese Kennzeichnung."},"D28":{"reason":"Merke dir beim Kontaktablauf zwei getrennte Ziele: Der Schutzleiter muss die Schutzverbindung passend zur Kontaktfolge sichern; ein Pilotkontakt kann eine dafür ausgelegte Lastschaltung steuern. Die mechanische Codierung verhindert nicht automatisch jede Fehlanwendung.","example":"Für eine vollständige Prüfungsantwort nennst du zunächst die Zuordnungsmerkmale der Steckvorrichtung und erklärst dann das Stecken und Ziehen in umgekehrter Reihenfolge. Welche Zusatzkontakte vorhanden sind, ist eine Eigenschaft der konkreten Ausführung, keine Selbstverständlichkeit jeder CEE-Verbindung."},"D29":{"reason":"Beispiel mit vier Ringen: Braun = 1, Schwarz = 0, Rot = Multiplikator 100, Gold = ±5 %. Die ersten zwei Stellen ergeben 10; 10 × 100 Ω = 1.000 Ω = 1 kΩ. Die Abweichung beträgt 50 Ω, also reicht der Toleranzbereich von 950 bis 1.050 Ω.","example":"Die Toleranz ist eine zulässige Abweichung vom Nennwert, keine zusätzliche Ziffer. Bei einer Aufschrift 4K7 steht der Buchstabe zugleich für Einheit und Dezimalstelle: 4,7 kΩ. Für fünf Farbringe und andere Codierungen gelten andere Stellenaufteilungen; das Vier-Ring-Schema darf nicht blind übertragen werden."},"D30":{"reason":"Ein Installationskanal ordnet und schützt Leitungen, muss aber zu Umgebung und Nutzung passen. Ein Bodenkanal wird anders beansprucht als ein Verdrahtungskanal im Schaltschrank. Zu den Auswahlpunkten gehören Platzreserve, Trennung, Zugänglichkeit, Temperatur und mechanische Beanspruchung.","example":"Ein leitfähiger Kanal kann in ein Schutz- beziehungsweise Potentialausgleichskonzept einzubeziehen sein. Ob und wie das geschieht, folgt aus der konkreten Schutzmaßnahme und den zugehörigen Vorgaben. „Metall leitet“ ist die physikalische Grundlage; die fachgerechte Ausführung braucht zusätzlich die Anlagenunterlagen."},"D31":{"reason":"Der Schaltplan beschreibt elektrische Funktionen und Verbindungen. Das Layout übersetzt diese in geometrische Leiterbahnen, Pads und Abstände. Eine elektrisch richtige Verbindung im Schaltplan kann auf einer Platine trotzdem schlecht geführt sein, etwa bei hohen Strömen oder empfindlichen Signalen.","example":"Beim subtraktiven Leiterbild entsteht das Muster aus einer zunächst kupferbeschichteten Fläche, indem ungewünschtes Kupfer entfernt wird. Isolationsabstände, Leiterbahnbreiten und Fertigungstoleranzen müssen vorher feststehen. Das Basismaterial trägt und isoliert; Kupferlage und Isolierstoff erfüllen unterschiedliche Aufgaben."},"D32":{"reason":"Die Verlustleistung muss vom Bauteil über seine Übergänge an die Umgebung gelangen. Bei einem vereinfachten stationären Modell gilt ΔT = P · Rth. Bei 5 W Verlustleistung und einem gesamten Wärmewiderstand von 10 K/W steigt die Temperatur rechnerisch um 50 K über die Umgebung.","example":"Zum Gesamtwärmewiderstand gehören mehrere Abschnitte, nicht nur der Kühlkörper. Wärmeleitpaste füllt kleine Unebenheiten, ersetzt aber keinen Kühlkörper und soll keinen unnötig dicken Spalt bilden. Luftbewegung, Einbaulage, Oberfläche und Umgebungstemperatur ändern die tatsächliche Wärmeabgabe."},"D33":{"reason":"Der Bemessungsstrom ist ein zugeordneter Betriebswert. Eine Sicherung löst nicht bei jeder beliebig kurzen Überschreitung augenblicklich aus; ihre Zeit-Strom-Kennlinie ist entscheidend. Bauform, Spannung, Ausschaltvermögen und Kennlinie müssen zur Anwendung passen.","example":"Der Kennmelder dient der erkennbaren Anzeige, der Passeinsatz verhindert bei passenden Systemen das Einsetzen unzulässig großer Bemessungsströme. Eine größere Sicherung einzusetzen, um wiederkehrendes Auslösen zu vermeiden, beseitigt keine Fehlerursache und kann die Schutzwirkung aufheben."},"D34":{"reason":"Beim Schließen und Öffnen eines Kontakts müssen Leitfähigkeit, mechanischer Verschleiß und Lichtbogenbeanspruchung zusammen betrachtet werden. Ein für kleine Messsignale günstiger Kontaktwerkstoff ist nicht automatisch die beste Wahl für große Schaltleistungen.","example":"Bei Gleichstrom fehlt der regelmäßige natürliche Stromnulldurchgang eines Wechselstroms. Dadurch kann das Löschen eines Lichtbogens anspruchsvoller sein. Die zulässige Gleichstrom-Schaltleistung eines Geräts lässt sich deshalb nicht einfach aus einer Wechselstromangabe übernehmen."},"D35":{"reason":"Ein Multilayer verbindet mehrere leitende Ebenen durch isolierende Schichten und geeignete Durchkontaktierungen. Die zusätzlichen Ebenen schaffen Platz für Verbindungen sowie definierte Versorgungs- und Bezugsebenen. Sie sind kein Stapel lose übereinandergelegter fertiger Platinen.","example":"Mehr Lagen können eine kompakte und elektrisch bessere Führung ermöglichen, erhöhen aber Fertigungs- und Prüfaufwand. Die tatsächliche Signalqualität hängt unter anderem von Rückstromwegen, Geometrie und Schichtaufbau ab. „Viele Lagen“ allein ist noch kein Qualitätsnachweis."},"D36":{"reason":"Ein Schrumpfschlauch wird vor der Verwendung größer als die zu umhüllende Stelle gewählt und verengt sich beim vorgesehenen Erwärmen. Das Schrumpfverhältnis beschreibt die Größenänderung. Zusätzlich müssen Wandstärke, Temperaturbereich, Werkstoff und gegebenenfalls Innenkleber passen.","example":"Für die Lagerung gilt, vorzeitiges Schrumpfen, Schädigung und Verunreinigung zu vermeiden. Die Kennzeichnung beziehungsweise Herstellerdaten bestimmen Lager- und Verarbeitungsvorgaben. Schrumpfen über einer scharfen Kante oder einer ungeeigneten Verbindung erzeugt nicht automatisch eine dauerhaft sichere Isolation."},"D37":{"reason":"Die Tragfähigkeit hängt vom Untergrund und vom gesamten Befestigungssystem ab. Tragendes Mauerwerk, Hohlziegel, Beton und Gipskarton übertragen Kräfte unterschiedlich. Eine Putzschicht ist nicht ohne Weiteres ein tragfähiger Verankerungsgrund.","example":"Bei einer Rohrbefestigung erläuterst du zuerst die Annahmen: Rohrgewicht, mögliche Zusatzlasten, Wandaufbau und Feuchtigkeit. Dann wählst du ein dafür zugelassenes System. Randabstände, Bohrloch, Verankerungstiefe und Montagevorgaben gehören zur Begründung; eine einzelne Dübelgröße ohne diese Angaben reicht nicht."},"D38":{"reason":"Adhäsion beschreibt die Haftung zwischen Klebstoff und Oberfläche, Kohäsion den inneren Zusammenhalt im Klebstoff. Eine Klebung kann daher an der Grenzfläche oder im Klebstoff selbst versagen. Die beiden Begriffe erklären verschiedene mögliche Schwachstellen.","example":"Eine große Überlappung kann günstiger sein als eine ungünstige Schälbeanspruchung. Saubere und geeignete Oberflächen, richtige Schichtdicke sowie passende Aushärtung beeinflussen die Verbindung. Ein sehr fester Klebstoff kann eine schlecht vorbereitete oder ungeeignete Oberfläche nicht beliebig ausgleichen."},"D39":{"reason":"Erwärmung entsteht unter anderem durch die elektrischen Verluste I² · R. Wie gut die Wärme abgeführt wird, hängt von Verlegung und Umgebung ab. Deshalb dürfen gleiche Querschnitte bei unterschiedlicher Häufung, Temperatur oder Wärmedämmung unterschiedliche zulässige Ströme haben.","example":"Die Auswahl verbindet Strombelastbarkeit, Schutzorgan, Spannungsfall und weitere Anforderungen. Eine Verlegeart ist keine willkürliche Bezeichnung, sondern ein definiertes thermisches Vergleichsmodell. Der notwendige Querschnitt darf nicht allein aus einer allgemeinen Zahl „Ampere je Quadratmillimeter“ abgelesen werden."},"D40":{"reason":"Eine Schraubensicherung kann unterschiedliche Ziele haben: ein Losdrehen verhindern, einen Verlust nach Vorspannkraftabbau verhindern oder Vorspannkraftverluste begrenzen. Diese Zwecke sind nicht gleich. Du benennst deshalb zuerst das Ziel und erst dann das geeignete Prinzip.","example":"Ein Splint an einer passenden Kronenmutter kann eine formschlüssige Verliersicherung bilden. Ein geeigneter Schraubensicherungsklebstoff wirkt anders und hängt von Werkstoff, Oberfläche und Temperatur ab. Die konkrete Wirksamkeit bei dynamischen Lasten muss zum System passen; ein beliebiger Federring ist keine universelle Lösung."},"D41":{"reason":"Bei der messtechnischen Einteilung erzeugt ein aktiver Wandler sein Messsignal aus der Messgröße, etwa die Thermospannung eines Thermoelements. Ein passiver Wandler verändert eine Eigenschaft und benötigt eine Auswertung mit Hilfsenergie; beim Pt100 wird der Widerstand erfasst.","example":"Ein Pt100 hat nominell 100 Ω bei 0 °C. Daraus folgt nicht, dass er eine eigene Ausgangsspannung von 100 V erzeugt. Analog oder binär beschreibt die Signalform. Im industriellen Sprachgebrauch wird „aktiv“ außerdem manchmal für gespeiste Ausgänge verwendet; der gemeinte Kontext muss klar sein."},"D42":{"reason":"Ein Potentiometer teilt über einen beweglichen Schleifer einen Widerstand auf. Bei einem idealen unbelasteten Spannungsteiler ist die Schleiferspannung bei gleichmäßiger Bahn proportional zur Position. Die Bewegung kann linear oder drehend sein.","example":"Beispiel: Eine gleichmäßige Bahn liegt an 10 V; in halber Stellung liegen ideal 5 V am Schleifer an. Ein angeschlossener Eingang belastet den Teiler und kann das Verhältnis verändern. Darum gehören Eingangswiderstand, Kontaktverschleiß und die erforderliche Genauigkeit zur realen Betrachtung."},"D43":{"reason":"Ordne Gesundheitsgefahren nach Einwirkungsart: beispielsweise Lärm, gefährliche Stoffe, mechanische Beanspruchung und ungünstige Ergonomie. Zu jeder Gefahr gehört eine passende Maßnahme. Eine allgemeine Aussage „Schutzkleidung tragen“ erklärt noch nicht, was gegen welche Einwirkung hilft.","example":"Sauber getrennte Metallreste können hochwertig verwertet werden; eine Verunreinigung mit Öl oder anderen Stoffen verändert die Behandlung. Abfallvermeidung und richtige Trennung beginnen am Arbeitsplatz. Ob ein Rest ein gewöhnlicher Wertstoff oder gefährlicher Abfall ist, hängt von seiner tatsächlichen Beschaffenheit ab."},"D44":{"reason":"Bei Kältemitteln sind Stoffidentität, Umweltwirkung und Gefährdungen getrennt zu betrachten. Zwei Stoffnamen ersetzen keine Beurteilung ihrer Eigenschaften. Die Fachpunkte nennen Beispiele; für den Umgang gelten die aktuellen produkt- und tätigkeitsbezogenen Vorgaben.","example":"Elektroaltgeräte gehören in Österreich zu den vorgesehenen Sammel- und Rücknahmesystemen. Ein Gerät kann Schadstoffe und zugleich verwertbare Metalle enthalten. Eigenmächtiges Öffnen von Kältekreisläufen oder unsachgemäße Entsorgung ist daher keine sinnvolle Form der Rohstoffgewinnung."},"D45":{"reason":"Die Schirmungsbezeichnung trennt Gesamtschirm und Aderpaarschirm. U/UTP bedeutet ohne Gesamtschirm und ohne Paarschirm; F/UTP besitzt einen Folienschirm insgesamt, die einzelnen Paare sind ungeschirmt. S/FTP beschreibt einen Geflechtschirm insgesamt und Folienschirme an den Paaren.","example":"Ältere Kürzel wie STP können ohne Zusatz mehrdeutig sein. Deshalb formulierst du die vollständige Bauart und beachtest Steckverbinder, Kategorie, Umgebung und Potentialausgleich. Eine hochwertige Leitung mit ungeeigneten Steckern oder fehlerhafter Schirmanbindung ergibt nicht automatisch eine hochwertige Gesamtverbindung."},"D46":{"reason":"Die Schutzart gilt für das fertig montierte Gehäuse mit geeigneten Einführungen. Eine passende Kabelverschraubung muss zum Kabeldurchmesser, Gewinde, Werkstoff und zur Umgebung passen. Ein zu kleines Kabel in einer ungeeigneten Dichtung kann trotz gutem Gehäuse undicht bleiben.","example":"Bei Schutzisolierung darf der Einbau die vorgesehene doppelte oder verstärkte Isolation nicht beeinträchtigen. Leitfähige Teile und Montageänderungen sind daher nach dem Schutzkonzept zu beurteilen. Schutzart gegen Eindringen und elektrische Schutzmaßnahme sind zwei verschiedene Eigenschaften."},"E1":{"reason":"Trenne den Diagnoseweg in Befehl, Ausgang, Leitung und Last. Ein gesetztes Programmbit beweist noch nicht, dass an der Ventilspule eine wirksame Spannung unter Last anliegt. Umgekehrt beweist eine leuchtende Ventilanzeige noch keine pneumatische Bewegung.","example":"Ein Transistorausgang muss zu Spannung, Strom, Lastart und Schutzbeschaltung passen. Ein Hilfsschütz lässt sich deshalb nicht allein wegen eines gleichen Steuersignals durch irgendeinen Halbleiterausgang ersetzen. Die Übertragungsrate beschreibt Daten pro Zeit und ist nicht identisch mit der vollständigen Reaktionszeit einer Anlage."},"E2":{"reason":"Eine Brückenschaltung nutzt bei intakter Funktion beide Halbwellen. Fällt ein Zweig aus, können Welligkeit und Gleichanteil deutlich verändert werden. Die gemessene Spannung hängt zusätzlich davon ab, ob geglättet wird, welche Last vorliegt und was das Messgerät tatsächlich erfasst.","example":"Eine belastbare Diagnose betrachtet daher Schaltung und Messbedingungen. Für die Diodenprüfung gelten die sichere Freischaltung und die geeignete Messmethode; parallele Stromwege können das Ergebnis verfälschen. Ein Kommunikationsprotokoll beschreibt vereinbarte Regeln des Datenaustauschs, nicht die elektrische Gleichrichtung."},"E3":{"reason":"Beim Startproblem einer Stern-Dreieck-Steuerung gehst du vom erwarteten Ablauf aus: Freigaben, Startbefehl, Schützansteuerung und vorgesehene Umschaltung. Jede Beobachtung wird mit der erwarteten Funktion verglichen, statt mehrere Bauteile auf Verdacht zu tauschen.","example":"Eine Verriegelung verhindert unzulässige gleichzeitige Schaltzustände. Sie darf bei der Fehlersuche nicht einfach umgangen werden. Die spätere Frage zur Topologie behandelt die Struktur eines Netzes, etwa Linie, Stern oder Ring; sie ist ein eigener fachlicher Teil dieser Prüfungsfrage."},"E4":{"reason":"Für einen Motoranschluss gehören Motordaten, Netz, Anlauf, Leitungslänge und Umgebung zusammen. Der Nennstrom ist eine wichtige Ausgangsgröße, aber kein vollständiger Leitungsnachweis. Schutz gegen Kurzschluss und gegen Überlast erfüllen unterschiedliche Aufgaben.","example":"Ein korrekt ausgewähltes Schutzgerät muss außerdem fachgerecht eingestellt und mit der Leitung koordiniert sein. Vor der Freigabe sind die vorgesehenen Prüfungen, Drehrichtung, Funktion und Dokumentation zu berücksichtigen. Die Lernantwort beschreibt die Planung; sie ersetzt keine praktische Anschluss- oder Prüffreigabe."},"E5":{"reason":"Erkläre jede Maßnahme über ihre Wirkung. Eine eindeutige Kennzeichnung verringert Verwechslungen, passende Schutzgeräte begrenzen bestimmte Fehlerfolgen und eine saubere Trennung verbessert Übersicht und Störfestigkeit. Die drei Ziele beeinflussen sich gegenseitig.","example":"Eine Anlage kann im Normalbetrieb funktionieren und trotzdem unsicher oder schlecht instandhaltbar sein. Zuverlässigkeit bedeutet mehr als „sie läuft gerade“. Für die Prüfung helfen drei Spalten: Ziel, konkrete Maßnahme und fachliche Begründung. Allgemeine Begriffe ohne Wirkungskette bleiben unvollständig."},"E6":{"reason":"Methodisches Suchen beginnt mit einer klaren Sollfunktion und einem reproduzierbaren Fehlerbild. Danach grenzt du den Fehler über geeignete Beobachtungen und fachgerechte Prüfungen ein. Erst ein bestätigter Befund rechtfertigt die zugehörige Abhilfe.","example":"Am idealisierten unterbrochenen Strompfad kann über der Unterbrechung eine Spannung auftreten, obwohl kein Betriebsstrom fließt. Das erklärt das Messprinzip, ist aber keine Aufforderung zu Messungen an Netzspannung. Messkategorie, sichere Arbeitsweise und fachliche Berechtigung sind gesondert zu beachten."},"E7":{"reason":"Zuerst klärst du den Umfang der Störung und die Voraussetzungen für eine sichere Prüfung. Betrifft sie eine Funktion oder die gesamte Anlage? Gab es Änderungen, eine Schutzabschaltung oder ungewöhnliche Umgebungsbedingungen? Diese Informationen lenken die weitere Eingrenzung.","example":"Eine Durchgangsprüfung, eine Isolationsmessung und eine Strommessung beantworten verschiedene Fragen. Eine Isolationsmessung kann empfindliche Elektronik beeinträchtigen, wenn sie ohne passende Trennung erfolgt. Deshalb wird das Messverfahren aus Schaltung und Prüfziel ausgewählt, nicht aus der bloßen Verfügbarkeit eines Geräts."},"E8":{"reason":"Eine Steuerung wird anhand von Ein- und Ausgängen, Ablauf, Reaktionszeiten, Kommunikation, Erweiterbarkeit und Instandhaltung ausgewählt. Die benötigte Sicherheitsfunktion ist zusätzlich zu betrachten. Ein normales SPS-Programm wird nicht allein durch Programmierung zu einer sicheren Steuerung.","example":"Bei häufigen Ablaufänderungen kann eine SPS Vorteile bieten; eine sehr einfache feste Funktion kann konventionell übersichtlich sein. Der Vergleich braucht die konkrete Aufgabe. Ein Vorteil der einen Lösung ist nicht automatisch in jeder kleinen oder großen Anlage ausschlaggebend."},"E9":{"reason":"Unterscheide Errichtungsanforderungen für Anlagen, Anforderungen an Maschinen und Prüfanforderungen für elektrische Betriebsmittel. Ein historischer Normverweis kann in alten Unterlagen vorkommen, ohne damit den heute anzuwendenden Regelstand vollständig zu beschreiben.","example":"Die ausführlichen Fachpunkte ordnen die im Katalog genannten Bezeichnungen ein. Für eine reale Abnahme muss zusätzlich der aktuelle verbindliche Anwendungsfall mit Ausgabe, Übergangsregelung und einschlägigen Unterlagen geklärt werden. Eine auswendig gelernte alte Nummer ist kein Ersatz für diese Zuordnung."},"E10":{"reason":"Vor dem Austausch prüfst du nicht nur die Bauform, sondern Funktion, elektrische Daten und Software- beziehungsweise Parametrierungsstand. Bei einer SPS können Programm, Hardwarekonfiguration und Kommunikation zusammenpassen müssen. Ein mechanisch passendes Ersatzteil ist noch kein nachgewiesener Ersatz.","example":"Beim Sensor gehören PNP/NPN beziehungsweise Schaltart, Versorgung, Anschluss, Schaltabstand und Umgebungsdaten dazu. Nach dem Tausch folgt die vorgesehene Funktionsprüfung und Wiederfreigabe. Sonst kann die eigentliche Fehlerursache bestehen bleiben oder ein neuer Fehler eingebaut werden."},"E11":{"reason":"Eine Pressverbindung entsteht durch eine genau abgestimmte plastische Verformung von Verbinder und Leiter. Querschnitt, Leiterklasse, Hülse, Werkzeug und Pressprofil bilden ein System. Ein zufällig passender Einsatz kann äußerlich eine Verbindung erzeugen, ohne die erforderliche Qualität nachzuweisen.","example":"Farbcodes können system- oder herstellerabhängig sein. Die in den Fachpunkten genannten Beispiele sind deshalb im jeweiligen Bezug zu lernen. Zur Beurteilung gehören Vorbereitung, vollständige Einstecktiefe und die vorgesehenen Sicht- beziehungsweise Zugprüfungen, nicht nur die Farbe der Isolation."},"E12":{"reason":"Ein Sensor kann elektrisch intakt sein und das Werkstück trotzdem nicht erkennen. Material, Abstand, Ausrichtung, Verschmutzung und Umgebungsbedingungen beeinflussen die Erfassung. Deshalb trennt eine gute Diagnose die elektrische Signalkette von der tatsächlichen Erfassungssituation.","example":"Bei der ersten Inbetriebnahme einer Zuführung prüfst du schrittweise definierte Funktionen und ihr Zusammenspiel nach dem freigegebenen Prüfplan. Das Protokoll macht nachvollziehbar, was unter welchen Bedingungen geprüft wurde und welche Abweichungen offen bleiben. Es dient nicht nur als Unterschrift am Schluss."},"E13":{"reason":"Übertemperatur ist eine Wirkung mit mehreren möglichen Ursachen: mechanische Überlast, elektrische Unsymmetrie oder unzureichende Kühlung können ähnlich aussehen. Die Abhilfe muss zur bestätigten Ursache passen. Ein höher eingestellter Motorschutz beseitigt die zusätzliche Erwärmung nicht.","example":"Bei blockierten Kühlwegen kann die Verlustleistung unverändert sein, während die Wärme schlechter abgegeben wird. Bei Überlast steigt die Beanspruchung und häufig auch der Strom. Für die Erklärung verbindest du Ursache, physikalische Wirkung und passende fachgerechte Maßnahme jeweils als Dreierkette."},"E14":{"reason":"Wartungsintervalle sollen Verschleiß und Alterung vor einem ungeplanten Ausfall beherrschbar machen. Reinigung, Schmierung, Prüfung und gegebenenfalls geplanter Austausch erfüllen unterschiedliche Zwecke. Die Arbeiten richten sich nach Anlage und Herstellerangaben.","example":"Eine klare SPS-Struktur verkürzt die Suche nach dem betroffenen Funktionsbereich. Aussagekräftige Namen, einheitliche Schnittstellen und dokumentierte Zustände erleichtern sowohl Wartung als auch Änderungen. Eine kurze Programmdatei allein ist nicht automatisch übersichtlich oder wartbar."},"E15":{"reason":"Rechenbeispiel: An 1 kΩ liegen 12 V. I = U/R = 0,012 A = 12 mA. P = U²/R = 144/1.000 = 0,144 W. Die Widerstandsauswahl muss eine passende zulässige Leistung mit Temperatur- und Einbaureserve berücksichtigen; die reine Rechnung ist noch keine vollständige Bauteilfreigabe.","example":"Für einen nicht einzeln verfügbaren Wert kannst du passende Werte in Reihe addieren oder mit der Parallelschaltungsformel kombinieren. Toleranzen und Einzelleistungen bleiben zu beachten. Ein belasteter Potentiometer-Schleifer verändert den idealen Spannungsteiler und darf nicht beliebig viel Strom führen."},"E16":{"reason":"Verfolge ein Beispiel vom Werkstück bis zur Anzeige: Ein Sensor liefert ein Signal, die SPS verarbeitet den Zustand und übergibt Daten über das Kommunikationsnetz an ein HMI oder Leitsystem. Eine Verbindung zum übergeordneten System fügt weitere Verarbeitung und Schutzgrenzen hinzu.","example":"Ein LINK beziehungsweise Kopplungselement ist nach seiner konkreten Funktion zu erklären. Es kann Netze oder Kommunikationsbereiche verbinden; daraus folgt nicht automatisch eine Protokollumsetzung oder Sicherheitsfreigabe. Beschrifte die Originalzeichnung mit Datenquelle, Verarbeitung, Transport und Empfänger."},"E17":{"reason":"Eine sichtbare Lötstelle kann unauffällig wirken und trotzdem elektrisch oder mechanisch mangelhaft sein. Sichtprüfung, elektrische Prüfung und gegebenenfalls weitergehende Qualitätsprüfung betrachten unterschiedliche Eigenschaften. Die richtige Lötstelle hängt von Werkstoff, Verfahren und Geometrie ab.","example":"MOS-Bauteile können durch elektrostatische Entladung geschädigt werden. Ein geeignetes ESD-Konzept umfasst Arbeitsplatz, Person, Werkzeuge, Verpackung und Handling. Eine einzelne ESD-Manschette ohne passendes Gesamtkonzept garantiert keinen Schutz. Außerdem müssen Temperatur und Einwirkzeit zum Bauteil passen."},"E18":{"reason":"Teile einen geplanten Umbau in Anforderungen und Risiken, Mechanik/Elektrik, Steuerung/Kommunikation sowie Prüfung/Dokumentation. So wird erkennbar, welche Auswirkungen eine scheinbar kleine Änderung auf das Gesamtsystem haben kann.","example":"Die vier Grundmaßnahmen der Instandhaltung haben verschiedene Ziele: Inspektion stellt einen Zustand fest, Wartung erhält ihn, Instandsetzung stellt ihn wieder her und Verbesserung erhöht die Zuverlässigkeit ohne die geforderte Funktion grundlegend zu ändern. Ein Lagerwechsel und eine Ursachenverbesserung sind daher nicht derselbe Arbeitsschritt."},"E19":{"reason":"Drei ähnliche Störungen können unterschiedliche Ursachen haben: fehlender Anlauf, falsche Drehrichtung und starke Erwärmung. Dokumentiere zuerst das genaue Verhalten und die Betriebsbedingungen. Danach ordnest du Mess- und Sichtbefunde dem passenden Fehlerbild zu.","example":"Eine elektrische Ursache wie ein Fehler in der Versorgung ist anders zu behandeln als eine mechanische Blockierung. Beim bloßen Tauschen von Motorteilen kann die falsche Ursache unbeachtet bleiben. Abhilfe und erneute Funktionsprüfung müssen sich auf den bestätigten Befund beziehen."},"E20":{"reason":"Die geforderte Stückzahl verbindet Bearbeitungszeit, Verfügbarkeit und notwendige Kapazität. Eine Anlage mit vielen nominellen Takten kann bei Störungen weniger gute Teile liefern als eine stabil laufende Lösung. Maßgeblich ist die tatsächlich erforderliche Leistung in geforderter Qualität.","example":"Für eine UND-Verknüpfung muss jeder benötigte Eingang wahr sein: A = 1 und B = 1 ergibt Q = 1; jede andere Kombination ergibt Q = 0. Kontaktplan und Funktionsplan können dieselbe Logik unterschiedlich darstellen. Ein Symbolwechsel ändert nicht die logische Funktion."},"E21":{"reason":"Robotereinsatz lohnt sich besonders bei passenden wiederkehrenden Aufgaben, erreichbaren Qualitätszielen und beherrschbaren Varianten. Greifer, Zuführung, Schutzkonzept, Programmierung und Wartung gehören zur Bewertung des gesamten Systems, nicht nur der Roboterpreis.","example":"Ein wiederverwendbarer Baustein bündelt eine klar abgegrenzte Funktion mit definierter Schnittstelle. Mehrere ähnliche Antriebe können damit nach demselben Konzept gesteuert werden. Wiederverwendung verlangt trotzdem eine korrekte Parametrierung und Prüfung jeder konkreten Einbindung."},"E22":{"reason":"Der gefährliche Bereich einer Roboterzelle wird nicht allein durch die sichtbare aktuelle Roboterposition bestimmt. Mögliche Bewegungen, gespeicherte Energie, Werkzeuge und transportierte Teile gehören zum Gefahrenbild. Betriebsart und zulässiger Zugang richten sich nach dem freigegebenen Sicherheitskonzept.","example":"Eine betätigte Not-Halt-Einrichtung ersetzt nicht automatisch Freischaltung und Beherrschung aller Energien für Wartungsarbeiten. Dokumentation muss Zuständigkeiten, Betriebsarten, sichere Verfahren und Reaktionen auf Störungen verständlich beschreiben. Die vorliegende Erklärung dient der Prüfung, nicht als alleinige Arbeitsanweisung."},"E23":{"reason":"Die Automatisierungspyramide ordnet Aufgaben, nicht zwingend einzelne Geräte räumlich an. Sensorik erfasst den Prozess, die SPS steuert, HMI/SCADA visualisiert beziehungsweise überwacht und übergeordnete Systeme planen Produktion und Ressourcen.","example":"Eine reale Netzzeichnung kann mehrere dieser Aufgaben auf gemeinsam genutzter Infrastruktur zeigen. Ein Gateway oder eine Cloud ist deshalb nicht automatisch eine zusätzliche feste Pyramidenstufe. Erkläre an der Zeichnung, welche Daten zwischen welchen Funktionen fließen und wo Zugriffsgrenzen liegen."},"E24":{"reason":"Kupfer kann Daten elektrisch übertragen und je nach System zugleich Energie führen. Glasfaser überträgt optisch und vermeidet eine galvanische Verbindung über die Datenfaser. Funk vermeidet eine feste Leitung, braucht aber ein geeignetes Konzept für Reichweite, Störungen und Verfügbarkeit.","example":"Zur Auswahl gehören Distanz, Datenrate, Echtzeitanforderungen, EMV, mechanische Beanspruchung und Wartbarkeit. Ein schneller Übertragungsstandard kann eine ungünstige Installation nicht beliebig kompensieren. Die gesamte Strecke einschließlich Anschlüssen und Umgebungsbedingungen ist zu beurteilen."},"E25":{"reason":"Trennen und Entgraten sind unterschiedliche Arbeitsschritte. Das Trennen erzeugt die gewünschte Länge beziehungsweise Form; Entgraten entfernt scharfe Kanten und verbessert Handhabbarkeit und Passung. Eine entgratete Kante ist nicht automatisch maßhaltig oder für jede weitere Bearbeitung fertig.","example":"Bei einer Serie gleicher Längen werden Bezug, Anschlag, Schnittfuge und Längenprüfung mitgedacht. Werkzeugwechsel und Benutzung folgen den Hersteller- und Betriebsanweisungen durch unterwiesene Personen. Die Lernantwort beschreibt die Grundgedanken, keine vollständige Freigabe für einen Scheibenwechsel."},"E26":{"reason":"Für eine ideale Verdrängerpumpe gilt näherungsweise Q = Vg · n, mit geometrischem Fördervolumen je Umdrehung Vg und Drehzahl n. Bei festem Vg und unveränderter Drehzahl ist die theoretische Fördermenge nicht einfach über eine Stellschraube frei veränderlich.","example":"Die reale nutzbare Menge kann durch Leckage kleiner werden. Kavitation, Verschleiß und Undichtigkeiten haben verschiedene Ursachen und Merkmale. Druck entsteht aus dem Strömungswiderstand und der Last im System; die Pumpe „liefert“ nicht unabhängig von der angeschlossenen Anlage einen festen Arbeitsdruck."},"E27":{"reason":"Ein Bussystem transportiert je nach Anwendung Prozessdaten, Parameter und Diagnoseinformationen. Physikalische Übertragung, Zugriffsregeln und Protokoll bilden verschiedene Ebenen. Eine gemeinsame Leitung allein erklärt noch nicht, wie die Teilnehmer verständlich miteinander kommunizieren.","example":"Simplex bedeutet nur eine Richtung, Halbduplex beide Richtungen abwechselnd und Vollduplex beide Richtungen gleichzeitig. Ein Funksprechgerät mit wechselnder Sprechrichtung veranschaulicht Halbduplex. Diese Richtungsbegriffe sagen allein noch nichts über Datenrate oder Teilnehmerzahl aus."},"E28":{"reason":"Die Auflösung eines optischen Schutzgeräts hängt mit der erkennbaren Objektgröße zusammen. Ein Gerät für Körperzugang ist nicht automatisch für Fingerschutz geeignet. Reichweite, Ansprechzeit, Anordnung und erforderliche Sicherheitsfunktion müssen gemeinsam passen.","example":"Ein bloß messendes Lichtgitter ist nicht automatisch eine Schutzeinrichtung für Personenschutz. Der erforderliche Sicherheitsabstand hängt vom gesamten Anhalte- und Erfassungskonzept ab. Er lässt sich nicht allein aus einer Herstellerangabe zur optischen Reichweite bestimmen."},"E29":{"reason":"Ein Hydraulikspeicher kann auch nach dem Abschalten Energie halten. Dabei wirken Gasdruck, Flüssigkeitsdruck und gegebenenfalls mechanische Lasten zusammen. Eine Druckanzeige an nur einer Stelle beweist nicht zwingend, dass jeder abgesperrte Teil sicher energiefrei ist.","example":"Bei geeigneten gasbelasteten Speichern wird das vom Hersteller vorgeschriebene Gas verwendet, typischerweise Stickstoff. Sauerstoff oder beliebige Druckluft ist kein Ersatz. Die Fachpunkte erklären die Speicherbauarten; Arbeiten und Prüfungen daran erfordern die zugehörigen Verfahren und fachliche Berechtigung."},"E30":{"reason":"Ein Transmitter wandelt eine Messgröße in ein normiertes beziehungsweise definiertes Ausgangssignal. Rechenbeispiel für 0 bis 10 bar mit 4 bis 20 mA: 12 mA liegt 8 mA über dem unteren Signalwert. 8/16 = 0,5; das entspricht 5 bar.","example":"Der Messbereich und das Signal müssen exakt zusammenpassen. 4 mA ist hier der untere gültige Messwert und nicht „kein Drucksensor vorhanden“. Diagnoseverhalten außerhalb des Messbereichs ist geräteabhängig. Digitale Ausgänge können zusätzlich Status und Parameter übertragen."},"E31":{"reason":"Stecker und Leitung müssen als System passen: Leiterdurchmesser, Leiterart, Aderisolation, Schirm, Zugentlastung und Übertragungskategorie sind zu beachten. Ein Crimpstecker für flexible Leiter ist nicht automatisch für einen eindrähtigen Installationsleiter geeignet.","example":"Eine Durchgangsprüfung erkennt nicht jeden Hochfrequenzfehler. Falsche Paarzuordnung oder zu stark aufgedrehte Paare können die Datenübertragung verschlechtern. Die geforderte Prüfung richtet sich daher nach der Verbindungsklasse und Anwendung. Eine unklare Aufgabenangabe wird vor der Auswahl fachlich geklärt."},"E32":{"reason":"Bei einer LSA-Verbindung durchdringt die geeignete Kontaktgeometrie die Isolation und kontaktiert den vorgesehenen Leiter. Das funktioniert nur im freigegebenen Bereich von Leiter und Isolation. „Ohne Abisolieren“ bedeutet nicht „für jeden beliebigen Draht geeignet“.","example":"Eine Glasfaser ist gegenüber elektromagnetischer Einkopplung in die Datenübertragung unempfindlich, braucht aber saubere optische Kontakte und zulässige Biegeradien. Kupferstrecken haben andere Stärken und Grenzen. Die Wahl hängt vom gesamten Einsatzfall ab."},"E33":{"reason":"Ein Transport wird von Masse, Schwerpunkt, Abmessungen und zulässigen Anschlagpunkten aus geplant. Die Tragfähigkeit eines Hebezeugs allein genügt nicht: Anschlagmittel, Lastwinkel, Fahrweg, Boden und Zugänglichkeit begrenzen das Gesamtsystem.","example":"Berechtigung und Unterweisung für das Kranführen sind nach dem österreichischen Anwendungsfall zu beurteilen. Ein Führerschein für ein anderes Fahrzeug ersetzt diese Voraussetzungen nicht automatisch. Die Fachpunkte ordnen die Anforderungen ein; ein realer Hebeplan und die zuständigen Personen bleiben notwendig."},"E34":{"reason":"Ablegereife bedeutet, dass ein Anschlagmittel nicht weiter eingesetzt werden darf. Sichtbare Drahtbrüche, Verformung, Korrosion oder andere Schäden sind anhand des konkreten Seiltyps und der geltenden Ablegekriterien zu beurteilen. Eine einzelne allgemeine Zahl ist nicht für alle Seile richtig.","example":"Ein beschädigtes Stahlseil wird nicht durch eine verringerte Schätzung der Last wieder sicher. Vor dem Transport gehören Prüfung, Lastaufnahme, Kommunikation und abgesperrter Gefahrenbereich zusammen. Die zulässige Belastung folgt der tatsächlichen Konfiguration des Systems."},"E35":{"reason":"Beim manuellen Transport helfen geeignete Hilfsmittel, die Kraft und ungünstige Körperhaltung zu vermindern. Handschuhe können Schnittverletzungen vorbeugen, ersetzen aber kein tragfähiges Transport- und Griffkonzept. Besonders Bleche verbinden scharfe Kanten mit großen Flächen und möglichem Kippen.","example":"An scharfen Lastkanten können Anschlagmittel stark beansprucht werden; geeigneter Kantenschutz muss zum System passen. Beim Rollen-Transport verändert ein Richtungswechsel die Auflage und den Schwerpunktbezug. Personen dürfen nicht zur provisorischen Sicherung in Quetsch- und Kippbereiche geraten."},"E36":{"reason":"Verdrillte Aderpaare verringern bei passender symmetrischer Übertragung die Störeinflüsse und gegenseitige Beeinflussung. Die beiden Adern eines Paares gehören elektrisch zusammen. Alle acht Adern nur irgendwie durchzuverbinden erhält diese Paarstruktur nicht.","example":"Ein Hub verteilt Signale auf seine Ports; ein Switch verarbeitet Ethernet-Frames und lernt, an welchem Port eine MAC-Adresse erreichbar ist. Ein Switch ist trotzdem nicht automatisch ein Router oder eine Firewall. Diese Geräte erfüllen andere Aufgaben im Netz."},"E37":{"reason":"Beim Löten schmilzt das Lot, während die verbundenen Grundwerkstoffe im üblichen Prozess nicht aufgeschmolzen werden. Gute Benetzung und passende Prozessbedingungen sind entscheidend. SMD beschreibt die Montage von Bauteilen auf Oberflächenpads, nicht ein einziges festes Lötverfahren.","example":"Beim Reflowverfahren wird aufgebrachtes Lot nach einem geeigneten Temperaturprofil aufgeschmolzen und anschließend kontrolliert abgekühlt. Entlötlitze und Entlötpumpe entfernen Lot auf unterschiedliche Weise. Übermäßige Wärme kann Pads oder Bauteile schädigen; ein glänzender Eindruck allein ist kein vollständiger Qualitätsnachweis."},"E38":{"reason":"Temporäre Variablen sind für lokale Zwischenergebnisse eines Aufrufs vorgesehen. Auf ihren vorherigen Inhalt darf nicht als dauerhafter Speicher vertraut werden. Statische Daten eines FB liegen im zugehörigen Instanzspeicher und können einen Zustand über Aufrufe hinweg erhalten.","example":"Für eine reine Berechnung aus Eingaben eignet sich häufig ein FC. Ein Antrieb mit gespeichertem Zustand oder einer zustandsabhängigen Funktion passt häufig zu einem FB mit eigener Instanz. Welche Daten nach Neustart erhalten bleiben, ist zusätzlich eine Frage der Retentivität und Konfiguration, nicht allein von „statisch“."},"E39":{"reason":"Ein brauchbares Protokoll ist eindeutig zuordenbar, vollständig für den Prüfzweck, nachvollziehbar und auswertbar. „Geprüft: passt“ lässt weder Messverfahren noch Betriebsbedingungen oder Grenzwerte erkennen. Ein späterer Vergleich wird dadurch schwierig.","example":"Ein nachvollziehbarer Eintrag verbindet Prüfobjekt, Datum, Verantwortliche, Verfahren, Ergebnis und Bewertung. Abweichungen sowie erforderliche Maßnahmen bleiben sichtbar. Leistungsdaten für die Auslegung beschreiben dagegen, was die Anlage leisten soll; sie sind von einem einzelnen erfolgreichen Probelauf zu unterscheiden."},"E40":{"reason":"Eine Schrittkette trennt den aktiven Zustand von der Bedingung für den Zustandswechsel. Beispiel: Schritt „Spannen“, Transition „gespannt bestätigt“, danach Schritt „Bearbeiten“. Die Aktion gehört zum Schritt; die Weiterschaltbedingung zur Transition.","example":"Ein Ablauf darf nicht allein wegen einer verstrichenen Zeit annehmen, dass eine gefährdungsrelevante mechanische Bewegung erfolgreich war. Rückmeldungen und Sicherheitskonzept bleiben wichtig. GRAPH/SFC kann den Ablauf übersichtlich darstellen, ersetzt aber keine Prüfung der Logik und möglichen Fehlerzustände."},"E41":{"reason":"Eine Onlineverbindung zeigt den aktuellen Zustand im Steuerungssystem und unterstützt Diagnosepuffer, Beobachtung und Fehlereingrenzung. Ein logisch gesetzter Ausgang im Programm beweist aber noch nicht, dass die physische Last korrekt arbeitet. Diagnose und reale Funktion müssen zusammenpassen.","example":"Forcen oder Ändern von Werten kann unmittelbar Bewegung auslösen und gehört nicht zu einer beliebigen Beobachtung. Für die Lernantwort unterscheidest du daher lesende Diagnose von einem Eingriff. Netzwerkzugang, Berechtigung und sicherer Anlagenzustand sind Teil des betrieblichen Verfahrens."},"E42":{"reason":"Bei einem dunklen HMI unterscheidest du Energieversorgung, Anzeigehardware und Betriebszustand. Bei falschen Werten kommen zusätzlich Datenquelle, Variablenzuordnung, Skalierung und Kommunikation infrage. Ein Neustart kann ein Symptom verändern, liefert aber noch keine bestätigte Ursache.","example":"Ein mobiler Zugang kann Wege verkürzen und Diagnose erleichtern, muss aber zum Zugriffs- und Sicherheitskonzept passen. Bildverarbeitung kann Merkmale prüfen und messen; ihre Eignung hängt von Beleuchtung, Optik, Bildqualität und Auswertung ab. Eine Kamera allein ist noch keine verlässliche Prüfanlage."},"E43":{"reason":"Koordinatenbezüge legen fest, relativ wozu eine Lage beschrieben wird. Wird ein Werkstück verschoben, kann ein korrekt definierter Werkstückbezug Anpassungen erleichtern. Der Werkzeugbezug beschreibt dagegen Position und Orientierung des wirksamen Werkzeugs gegenüber dem Flansch.","example":"Ein Achsantrieb muss unter anderem Drehmoment, Dynamik, Regelbarkeit und Genauigkeit erfüllen. Die benötigten Werte hängen von Last und Bewegung ab. SCARA oder Knickarm beschreibt eine Kinematik; elektrisch, hydraulisch oder pneumatisch beschreibt das Antriebskonzept. Diese Einteilungen beantworten verschiedene Fragen."},"E44":{"reason":"Beim Schmelzschweißen schmilzt der Grundwerkstoff im Fügebereich und erstarrt zur Naht. Eine stoffschlüssige Verbindung beruht auf dem Zusammenhalt der Werkstoffe im Verbindungsbereich. Beim Löten schmilzt dagegen das Lot und nicht im gleichen Sinne der Grundwerkstoff.","example":"Schweißen kann dichte und tragfähige Verbindungen mit wenig zusätzlichen Verbindungsteilen ermöglichen. Wärmeeintrag kann aber Verzug und Gefügeänderungen verursachen. Eine unlösbare Verbindung vereinfacht nicht automatisch spätere Reparaturen. Nicht jedes Schweißverfahren ist ein Schmelzschweißverfahren."},"E45":{"reason":"Eine typische federbetätigte Haltebremse hält im eingefallenen Zustand eine bereits stillstehende Achse. Das normale geregelte Abbremsen übernimmt der Antrieb. Haltemoment und zulässige dynamische Bremsfälle sind unterschiedliche Angaben.","example":"Bei Energieausfall kann eine Achse trotz vorhandener Bremse besondere Sicherungsmaßnahmen erfordern. Die Bremse ist keine pauschale Freigabe für Arbeiten unter einer Last. Der TCP ist der definierte wirksame Werkzeugpunkt; er kann räumlich weit vom Flansch entfernt liegen und besitzt einen zugehörigen Orientierungsbezug."},"E46":{"reason":"Gehe die sechs Bedingungen an einem Beispiel durch: Eine Montagezelle benötigt klare Anforderungen, richtige Montage, unterwiesenes Personal, funktionierende Schnittstellen, passende Aufstellung und geeignete Standortbedingungen. Eine einzelne funktionierende Bewegung beweist noch nicht das Zusammenwirken aller sechs Bereiche.","example":"Eine schwankende Druckluftversorgung am Standort kann eine korrekt montierte Pneumatikfunktion beeinträchtigen. Ein fehlerhaft abgestimmtes Übergabesignal kann zwei einzeln funktionierende Maschinen im Verbund stoppen. Diese Beispiele erklären, warum Inbetriebnahme über „einschalten und ausprobieren“ hinausgeht."},"E47":{"reason":"Qualitätsmanagement gestaltet Ziele und Prozesse so, dass Anforderungen zuverlässig erfüllt werden. Qualitätslenkung beobachtet und beeinflusst den laufenden Prozess. Qualitätssicherung schafft Vertrauen in die Erfüllung; Verbesserung verändert den Prozess auf Grundlage der Ergebnisse.","example":"KVP-Beispiel: Wiederkehrende Montagefehler erfassen, Ursache untersuchen, eine Änderung erproben, ihre Wirkung messen und die wirksame Lösung standardisieren. TQM bezieht Qualität über die ganze Organisation ein. Endkontrolle allein kann Fehler entdecken, verhindert ihre Entstehung aber nicht automatisch."},"E48":{"reason":"Ein Repeater empfängt und erneuert das elektrische Signal und verbindet damit Segmente. Er ist nicht automatisch ein Protokollübersetzer. Im Originalbild sind daher die elektrischen Segmentgrenzen zu markieren, bevor du über Busabschlüsse sprichst.","example":"Jedes elektrische RS-485-Segment benötigt die dafür vorgesehenen Abschlüsse an seinen physischen Enden. Die beiden äußersten Enden des gesamten Netzes reichen bei mehreren Segmenten nicht als Betrachtung. Versorgung und Ausführung der aktiven Abschlüsse sowie zulässige Längen und Teilnehmerzahlen folgen den konkreten PROFIBUS-Unterlagen."}};
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function switchHTML(mode,global=false){return '<div class="detail-switch '+(global?'global-detail-switch':'')+'" role="group" aria-label="Erklärungstiefe"><span>Antworten anzeigen</span>'+[['summary','Zusammengefasst'],['detailed','Ausführlich erklärt']].map(([value,label])=>'<button type="button" class="button '+(mode===value?'primary':'secondary')+'" data-action="answer-depth" data-depth="'+value+'" aria-pressed="'+(mode===value)+'">'+label+'</button>').join('')+'</div>';}
  function firstSentence(text){const match=text.match(/^.*?[.!?](?=\s+[A-ZÄÖÜ]|$)/);return match?match[0]:text;}
  function summaryHTML(card){return '<div class="answer-short">'+card.answer.map(a=>'<section><h3>'+esc(a.label)+'</h3><p>'+esc(firstSentence(a.text))+'</p></section>').join('')+'</div><p class="small-muted">Kurzfassung zum Wiederholen. Begründungen, Grenzen und Beispiele stehen unter „Ausführlich erklärt“.</p>';}
  function detailedHTML(card){const n=DETAILS[card.id];if(!n)return '';return '<section class="explain-detail"><div class="eyebrow">SCHRITT FÜR SCHRITT VERSTEHEN</div><h3>Wie die Fachpunkte zusammenhängen</h3><p>'+esc(n.reason)+'</p><h3>Praxis, Rechenweg und genaue Abgrenzung</h3><p>'+esc(n.example)+'</p><h3>So baust du deine eigene Erklärung auf</h3><ol>'+card.answer.map(a=>'<li><strong>'+esc(a.label)+'</strong>: Erkläre den Zusammenhang in eigenen Worten und nenne die dafür entscheidenden Eigenschaften oder Bedingungen.</li>').join('')+'</ol><p class="small-muted">Die vollständigen Fachpunkte und ihre Quellen gehören dazu. Diese Vertiefung ist ein Lernbeispiel; konkrete Anlagen, Grenzwerte und Herstellerangaben müssen zum Anwendungsfall passen.</p></section>';}
  const api={DETAILS,switchHTML,firstSentence,summaryHTML,detailedHTML};root.LernpassExplanations=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
